struct ElicitationSummaryView: View {
  let part: ElicitationSummaryPart

  var body: some View {
    VStack(alignment: .leading, spacing: 12) {
      // 1. User-visible message — large, primary
      Text(part.userVisibleMessage)
        .font(.body)

      // 2. "What I understand" — userGoal as a quote-style block
      if !part.userGoal.isEmpty {
        Label(part.userGoal, systemImage: "target")
          .font(.callout)
          .foregroundStyle(.secondary)
      }

      // 3. Concepts I'm tracking — list with gist anchors
      if !part.inferredConcepts.isEmpty {
        SectionHeader("Concepts I'm tracking")
        ForEach(part.inferredConcepts) { concept in
          HStack {
            Text(concept.label).font(.caption.weight(.medium))
            if let anchor = concept.proposedGistAnchor {
              Text("→ \(anchor)").font(.caption).foregroundStyle(.secondary)
            }
            if concept.ambiguous { Image(systemName: "questionmark.circle") }
          }
        }
      }

      // 4. Unresolved vocabulary
      if !part.unresolvedVocabulary.isEmpty {
        SectionHeader("Things I'm not sure about yet")
        ForEach(part.unresolvedVocabulary, id: \.self) { Text("• \($0)").font(.caption) }
      }

      // 5. Suggested patterns (collapsible — disclosure group)
      if !part.suggestedPatterns.isEmpty {
        DisclosureGroup("Patterns that might help (\(part.suggestedPatterns.count))") {
          ForEach(part.suggestedPatterns) { pattern in
            VStack(alignment: .leading, spacing: 4) {
              Text(pattern.typeLabel).font(.caption.weight(.medium))
              Text(pattern.description).font(.caption)
              Text(pattern.snippet).font(.caption.monospaced()).foregroundStyle(.secondary)
            }
          }
        }
      }

      // 6. Next actions
      if !part.nextActions.isEmpty {
        SectionHeader("What I'd do next")
        ForEach(part.nextActions, id: \.self) { Text("• \($0)").font(.caption) }
      }

      // Error indicators
      if part.alignerErrored { Label("Gist alignment unavailable this turn", systemImage: "exclamationmark.triangle").font(.caption2).foregroundStyle(.orange) }
      if part.retrieverErrored { Label("Pattern suggestions unavailable this turn", systemImage: "exclamationmark.triangle").font(.caption2).foregroundStyle(.orange) }
