```swift
import Foundation
import SwarmAgent

enum GistAlignerAgent {
  @MainActor
  static func make(viewModel: OntologyViewModel) -> Agent {
    Agent(
      name: "GistAligner",
      instructions: instructions,
      tools: tools(for: viewModel),
      memory: ConversationMemory(maxMessages: 50),
      configuration: AgentConfiguration(name: "GistAligner", maxIterations: 3)
    )
  }

  @MainActor
  private static func tools(for viewModel: OntologyViewModel) -> [any AnyJSONTool] {
    let oneTools: [any OneTool] = [
      SearchOntologyMemoryTool(viewModel: viewModel),
      ExplainGistConceptTool(viewModel: viewModel)
    ]
    return oneTools.map { $0.asAnyJSONTool() }
  }
}
```

Instructions must require JSON-array-only output. For each concept, output:

```json
{
  "concept": "<user's word, verbatim>",
  "candidates": [
    { "gistType": "gist:Activity", "confidence": 0.85, "rationale": "..." },
    { "gistType": "gist:Event", "confidence": 0.70, "rationale": "..." }
  ],
  "ambiguous": true
}
```

Constraints:
- Output is only a JSON array of objects. No prose and no markdown fences.
- Use `search_ontology_memory` filtered/phrased toward gist and `explain_gist_concept` to ground candidates in the actual gist projection.
- Do not invent gist types; only reference loaded gist package types.
- maxIterations: 3 for one-shot retrieval and ranking.
- Tools explicitly do not include `record_elicitation`; the Interviewer owns turn-summary writing.

