Implementation as an OrchestrationStep wrapping existing ChangeIntentWriter:

```swift
import Foundation
import SwarmAgent

struct CommitterStep: OrchestrationStep {
  let viewModel: OntologyViewModel

  func execute(input: String, context: OrchestrationStepContext) async throws -> AgentResult {
    let payload = try CommitterInput.decode(input)  // composed by parent workflow
    let sandbox = try await activeSandbox()
    let writer = ChangeIntentWriter(client: viewModel.typeDBClient, sandbox: sandbox)

    // 1. Apply schema delta to ACTIVE sandbox (no longer shadow). Also persists the
    //    extended ChangeIntent fields from 38.4.11 (judgeVerdict, retryCount, rejectionTrail).
    let intentId = try await writer.applySchemaDelta(
      forwardTypeql: payload.delta.typeql,
      reverseTypeql: payload.delta.reverseTypeql,
      action: deriveAction(from: payload.delta.typeql),
      targetLabel: payload.primaryTargetLabel,
      targetKind: payload.primaryTargetKind,
      renameFrom: payload.renameFrom,
      motivation: payload.delta.rationale,
      groupTag: payload.turnId,
      judgeVerdict: "accept",
      rejectionTrail: payload.rejectionTrail,
      retryCount: payload.retryCount
    )

    // 2. If migration plan: apply migration TypeQL, write MigrationPlan entity, link via deltaMigration.
    if let migration = payload.migrationPlan, !migration.planTypeql.isEmpty {
      try await applyMigration(migration, intentId: intentId, sandbox: sandbox, viewModel: viewModel)
    }

    // 3. For each claimedCQ:
    //    - Update CompetencyQuestion.cqStatus to "answered"
    //    - Set CompetencyQuestion.typeqlForm
    //    - Create deltaSatisfiesCQ relation
    for claimed in payload.delta.claimedCQs {
      try await updateCQAsAnswered(
        cqId: claimed.cqId,
        typeqlForm: claimed.typeqlForm,
        intentId: intentId,
        sandbox: sandbox
      )
    }

    // 4. Create deltaFromTurn relation linking the new ChangeIntent to the originating turn.
    try await linkDeltaToTurn(intentId: intentId, turnId: payload.turnId, sandbox: sandbox)

    // 5. Run the migration's verificationTypeql (if migration present) and abort/rollback
    //    if verification returns rows (would mean orphaned data).
    if let migration = payload.migrationPlan, !migration.verificationTypeql.isEmpty {
      let verifyResult = try await viewModel.typeDBClient.oneShotQuery(
        query: migration.verificationTypeql,
        databaseName: sandbox.name,
        transactionType: .read,
        commit: false
      )
      if !verifyResult.rows.isEmpty {
        // Migration left orphans; this is a Committer-side failure.
        // Roll back via reverseTypeql + log the failure.
        try await rollback(intentId: intentId, sandbox: sandbox)
        throw OneAgentError.toolExecutionFailed(
          toolName: "Committer",
          underlyingError: "Migration verification failed: \(verifyResult.rows.count) orphaned rows"
        )
      }
    }

    // 6. UI refresh — refresh the parsed schema cache + invalidate pinned packages,
    //    same pattern as ApplySchemaDeltaTool's post-write block.
    await refreshUI(viewModel: viewModel, sandbox: sandbox)

    return AgentResult(
      output: "{\"committed\": true, \"intentId\": \"\(intentId)\"}",
      toolCalls: [],
      toolResults: [],
      iterationCount: 1,
      duration: .zero,
      tokenUsage: nil,
      metadata: ["intentId": .string(intentId.description)]
    )
  }
}

struct CommitterInput: Codable, Sendable {
  let delta: GeneratedDelta            // from 38.4.13
  let migrationPlan: MigrationPlan?    // from 38.4.15, nil for additive
  let turnId: String                   // from the originating ConversationTurn (38.4.2/38.4.3)
  let primaryTargetLabel: String       // derived: first targetLabel from delta
  let primaryTargetKind: String        // derived: kind of primaryTargetLabel
  let renameFrom: String?              // populated when action is rename
  let rejectionTrail: String?          // null for first-attempt accepts; populated for after-retry
  let retryCount: Int                  // 0 if first attempt accepted
}
```

Key design choices:

1. Wraps existing ChangeIntentWriter rather than re-implementing the persistence path. The writer already handles transaction lifecycle, ID generation, and the existing ChangeIntent insert. This task adds the new field persistence (depends on 38.4.11 having extended the writer signature).

2. Migration verification is a post-apply check. If it fails, we roll back. This means the user sees a hard error rather than a silent broken sandbox. Acceptable for v1; if rollback proves expensive, consider verifying against the shadow sandbox in the Judge instead (move to 38.4.14).

3. CQ status update is per-claim. If even one claimed CQ fails to update (e.g., the cqId doesn't exist), the Committer fails the whole commit and rolls back. The Judge should have caught this earlier, but defensive.

4. Returns a structured AgentResult so the parent workflow can log success and the chat surface can display the commit confirmation.

