DriftReport:
  public struct DriftReport {
    public let driftAtoms: [SchemaAtom]
    public var isEmpty: Bool { driftAtoms.isEmpty }
  }

  public struct SchemaAtom: Hashable {
    public let kind: AtomKind
    public let label: String
  }

  public enum AtomKind: String, Hashable, CaseIterable {
    case entity, attribute, relation, role, owns, sub, function
  }

DriftDetector algorithm:

  func detectDrift(sandbox: SandboxHandle, client: OntologyTypeDBClient) async throws -> DriftReport {
    let meta = try await client.readSandboxMeta(from: sandbox.name)
    let sourceName = meta?.sourceName ?? "knowledge"  // legacy fallback

    // Build reference DB from source; apply non-untracked intents in order
    let reference = try await buildReferenceDB(
      from: sourceName,
      applyingIntents: (try await reader.ordered()).filter { $0.action != "untracked" }
    )

    let replayAtoms = try await atoms(of: reference)

    let untrackedAtoms: Set<SchemaAtom> = Set(
      (try await reader.ordered())
        .filter { $0.action == "untracked" }
        .compactMap { intent in
          guard let kind = AtomKind(rawValue: intent.targetKind) else { return nil }
          return SchemaAtom(kind: kind, label: intent.targetLabel)
        }
    )

    let accepted = replayAtoms.union(untrackedAtoms)
    let real = try await atoms(of: sandbox)
    let driftSet = real.subtracting(accepted)

    try await dropReference(reference)
    return DriftReport(driftAtoms: Array(driftSet).sorted(by: atomOrdering))
  }

  // Atom extraction from a parsed schema
  func atoms(of db: Database) async throws -> Set<SchemaAtom> {
    let parsed: ParsedSchema = try TypeQLParser.parse(try await db.typeSchema())
    var atoms: Set<SchemaAtom> = []

    for entity in parsed.entities {
      atoms.insert(SchemaAtom(kind: .entity, label: entity.name))
      if let parent = entity.parentEntity {
        atoms.insert(SchemaAtom(kind: .sub, label: "\(entity.name).sub"))
      }
      for own in entity.owns {
        atoms.insert(SchemaAtom(kind: .owns, label: "\(entity.name).\(own.attribute)"))
      }
    }

    for relation in parsed.relations {
      atoms.insert(SchemaAtom(kind: .relation, label: relation.name))
      if let parent = relation.parentRelation {
        atoms.insert(SchemaAtom(kind: .sub, label: "\(relation.name).sub"))
      }
      for own in relation.owns {
        atoms.insert(SchemaAtom(kind: .owns, label: "\(relation.name).\(own.attribute)"))
      }
      for role in relation.roles {
        atoms.insert(SchemaAtom(kind: .role, label: "\(relation.name).\(role.name)"))
      }
    }

    for attribute in parsed.attributes {
      atoms.insert(SchemaAtom(kind: .attribute, label: attribute.name))
    }

    for function in parsed.functions {
      atoms.insert(SchemaAtom(kind: .function, label: function.name))
    }

    return atoms
  }

Function atom caveat (documented): only presence is tracked. If a function body changes out-of-band, atoms are equal before and after (same name = same atom), and no drift is detected. This is a known v1 limitation. Full function-drift detection requires body-hash atoms — deferred to post-v1.

No auto-synthesis in THIS task; that's 6.2.

Atom ordering (for stable output):
  Sort by (kind.rawValue, label) — lexicographic.

