## Solution

### Option 1: Client-side recursive delete

**Add recursive delete method to BeadsClient:**

```swift
// OneApps/Beads/Backend/BeadsClient.swift
func deleteIssueWithChildren(_ id: String) async throws {
    // Get issue details to find children
    let issue = try await showIssue(id)

    // Recursively delete children first (depth-first)
    if let dependents = issue.dependents {
        for dep in dependents where dep.dependencyType == "parent-child" {
            try await deleteIssueWithChildren(dep.id)
        }
    }

    // Delete this issue
    try await deleteIssue(id)
}
```

**Update BeadsTreeView delete handler:**

```swift
Button("Delete", role: .destructive) {
    if let node = deleteAlertNode, let client = beadsClient {
        Task {
            if node.issue.issueType == .epic || node.issue.issueType == .feature {
                // Cascade delete for containers
                try? await deleteRecursively(node: node, client: client)
            } else {
                // Simple delete for tasks/bugs/chores
                try? await client.deleteIssue(node.issue.id)
            }
            await loadIssues()
        }
    }
}

private func deleteRecursively(node: BeadNode, client: BeadsClient) async throws {
    // Delete children first (depth-first traversal)
    for child in node.children {
        try await deleteRecursively(node: child, client: client)
    }
    // Then delete this node
    try await client.deleteIssue(node.issue.id)
}
```

